#define HK_INPUT_BITS ((1u << HK_IN_TICK) | (1u << HK_IN_VALUE) | (1u << HK_IN_VALUE2) | (1u << HK_IN_ISON) | \
		       (1u << HK_RUM1) | (1u << HK_RUM2)) /* SOMVR_INPUT=1 (RUM1/RUM2 also need SOMVR_RUMBLE) */
