enum { FS_LIFE, FS_SPECT, FS_PHOTO, FS_MOUNT, FS_FSM, FS_PRES_CAM, FS_CINE, FS_COMBAT, FS_SERVER, FS_SYNC, FS_SYNC_REC,
       FS_STRUGGLE_SYNC, FS_STRUGGLE_STATE, FS_TAGS, FS_TAG_COUNT, FS_RECNAME, FS_ATTACH, FS_N };
